function applyLanguage(lang){
  localStorage.setItem('ta-lang',lang);
  document.documentElement.lang=lang;
  document.querySelectorAll('[data-lang-toggle]').forEach(btn=>btn.classList.toggle('fr',lang==='fr'));
  const rev=Object.fromEntries(Object.entries(TA_TRANSLATIONS).map(([en,fr])=>[fr,en]));
  const map=lang==='fr'?TA_TRANSLATIONS:rev;
  document.querySelectorAll('[data-fr][data-en]').forEach(el=>{el.textContent=lang==='fr'?el.dataset.fr:el.dataset.en;});
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key=el.dataset.i18n;
    if(TA_TRANSLATIONS[key] || rev[key]) el.textContent=lang==='fr'?(TA_TRANSLATIONS[key]||key):(rev[key]||key);
  });
  const skip=new Set(['SCRIPT','STYLE','NOSCRIPT','TEXTAREA']);
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(n){return n.parentElement&&!skip.has(n.parentElement.tagName)&&n.nodeValue.trim()?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;}});
  const nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(n=>{const raw=n.nodeValue; const t=raw.trim(); if(map[t]) n.nodeValue=raw.replace(t,map[t]);});
  document.querySelectorAll('[data-placeholder-fr][data-placeholder-en]').forEach(el=>{el.setAttribute('placeholder',lang==='fr'?el.dataset.placeholderFr:el.dataset.placeholderEn);});
  document.querySelectorAll('[data-fr-placeholder][data-en-placeholder]').forEach(el=>{el.setAttribute('placeholder',lang==='fr'?el.dataset.frPlaceholder:el.dataset.enPlaceholder);});
  document.querySelectorAll('[data-fr-label][data-en-label]').forEach(el=>{el.setAttribute('aria-label',lang==='fr'?el.dataset.frLabel:el.dataset.enLabel);});
  document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{const ph=el.getAttribute('placeholder'); if(map[ph]) el.setAttribute('placeholder',map[ph]);});
  document.querySelectorAll('option').forEach(el=>{const t=el.textContent.trim(); if(map[t]) el.textContent=map[t];});
}
function initLanguage(){
  const lang=localStorage.getItem('ta-lang')||'fr';
  applyLanguage(lang);
  document.querySelectorAll('[data-lang-toggle]').forEach(btn=>{
    if(btn.dataset.boundLang) return;
    btn.dataset.boundLang='true';
    btn.addEventListener('click',()=>applyLanguage((localStorage.getItem('ta-lang')||'fr')==='fr'?'en':'fr'));
  });
}
function initUI(){
  initLanguage();
  document.querySelectorAll('[data-theme-toggle]').forEach(btn=>{
  if(btn.dataset.boundTheme) return;
  btn.dataset.boundTheme='true';
  btn.addEventListener('click',()=>{
    const next=!document.documentElement.classList.contains('dark');
    document.documentElement.classList.toggle('dark',next);
    localStorage.setItem('ta-theme',next?'dark':'light');
  });
  });
  window.closeDropdowns = function() {
    document.querySelectorAll("[data-dropdown].open").forEach((dropdown) => {
      dropdown.classList.remove("open");
    });
  };

  window.closeMobilePanelsExcept = function(except) {
    if (except !== "mobile") document.body.classList.remove("mobile-open");
    if (except !== "filters") document.body.classList.remove("filters-open");
    if (except !== "search") document.body.classList.remove("index-search-open");
    if (except !== "stats") document.body.classList.remove("index-stats-open");
    if (except !== "dropdown") window.closeDropdowns();
  };

  window.closeAllMobilePanels = function() {
    document.body.classList.remove(
      "mobile-open",
      "filters-open",
      "index-search-open",
      "index-stats-open"
    );
    window.closeDropdowns();
  };

  document.querySelectorAll('[data-dropdown]').forEach(drop=>{
    const btn=drop.querySelector('[data-dropdown-btn]');
    if(drop.dataset.boundDropdown) return;
    drop.dataset.boundDropdown='true';
    btn&&btn.addEventListener('click',(e)=>{
      e.stopPropagation();
      const willOpen = !drop.classList.contains('open');
      window.closeMobilePanelsExcept("dropdown");
      window.closeDropdowns();
      if (willOpen) {
        drop.classList.add('open');
      }
    });
  });
  if(!document.documentElement.dataset.boundDropdownClose){
    document.documentElement.dataset.boundDropdownClose='true';
    document.addEventListener('click', (e) => {
      if (e.target.closest('.tta-dropdown-menu-proto, #mobileFiltres, .mobile-search-panel, .main-nav, .card')) {
        return;
      }
      window.closeAllMobilePanels();
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === "Escape") {
        window.closeAllMobilePanels();
      }
    });
  }
  const mb=document.querySelector('[data-mobile]');
  if(mb&&!mb.dataset.boundMobile){
    mb.dataset.boundMobile='true';
    mb.addEventListener('click',(e)=>{
      e.stopPropagation();
      const willOpen = !document.body.classList.contains('mobile-open');
      window.closeAllMobilePanels();
      if (willOpen) {
        document.body.classList.add('mobile-open');
      }
    });
  }

  document.querySelectorAll('[data-mobile-search-toggle]').forEach(btn => {
    if(btn.dataset.boundSearchToggle) return;
    btn.dataset.boundSearchToggle = 'true';
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const willOpen = !document.body.classList.contains('index-search-open');
      window.closeAllMobilePanels();
      if (willOpen) {
        document.body.classList.add('index-search-open');
      }
    });
  });

  document.querySelectorAll('[data-mobile-filters-toggle]').forEach(btn => {
    if(btn.dataset.boundFiltersToggle) return;
    btn.dataset.boundFiltersToggle = 'true';
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const willOpen = !document.body.classList.contains('filters-open');
      window.closeAllMobilePanels();
      if (willOpen) {
        document.body.classList.add('filters-open');
      }
    });
  });
  document.querySelectorAll('[data-save]').forEach(btn=>{
    if(btn.dataset.boundSave) return;
    btn.dataset.boundSave='true';
    btn.addEventListener('click',(e)=>{e.preventDefault();btn.classList.toggle('saved');btn.textContent=btn.classList.contains('saved')?'Saved':'Save';toast(btn.classList.contains('saved')?'Job saved':'Job removed','good')});
  });
  document.querySelectorAll('[data-toast]').forEach(btn=>{
    if(btn.dataset.boundToast) return;
    btn.dataset.boundToast='true';
    btn.addEventListener('click',()=>toast(btn.dataset.toast, btn.dataset.type||'good'));
  });
  document.querySelectorAll('form[data-validate]').forEach(form=>{
    if(form.dataset.boundValidate) return;
    form.dataset.boundValidate='true';
    form.noValidate=true;
    form.addEventListener('input',(e)=>validateField(e.target,false));
    form.addEventListener('submit',(e)=>{
        const form = e.target.closest("form");
        if (!form) return;
        let ok=true;
        form.querySelectorAll('[required], input[type=email], input[type=password]').forEach(el=>{
            if(!validateField(el,true)) ok=false
        });
        if(!ok){
            e.preventDefault();
            form.classList.add('shake');
            setTimeout(()=>form.classList.remove('shake'),320);
            toast('Fix highlighted fields','bad');
            return;
        }
        if (form.matches("[data-auth-form='true']")) {
            return;
        }

        // If it's a real POST form with an action, let it submit naturally to the server.
        const isPost = form.getAttribute('method') && form.getAttribute('method').toLowerCase() === 'post';
        if (isPost && form.getAttribute('action')) {
            return;
        }

        // Only prevent default and show toast for dummy/prototype forms without real post action
        e.preventDefault();
        if (form.dataset.success) {
            toast(form.dataset.success, 'good');
        }
    });
  });
  document.querySelectorAll('[data-tab-target]').forEach(btn=>{
  if(btn.dataset.boundTab) return;
  btn.dataset.boundTab='true';
  btn.addEventListener('click',()=>{
    const group=btn.dataset.tabGroup; const target=btn.dataset.tabTarget;
    document.querySelectorAll(`[data-tab-group="${group}"]`).forEach(b=>b.classList.toggle('active',b===btn));
    document.querySelectorAll(`[data-tab-panel="${group}"]`).forEach(p=>p.style.display=p.dataset.panelName===target?'block':'none');
  });
  });
  initDjangoToasts();
  initModals();
  initSavedJobsEmptyState();
}
function validateField(el,show){ if(!el || !el.matches('input,textarea,select')) return true; let bad=false, success=false; if(el.required && !el.value.trim()) bad=true; if(el.type==='email' && el.value && !/^\S+@\S+\.\S+$/.test(el.value)) bad=true; if(el.type==='password' && el.value && el.value.length<6) bad=true; if(el.classList.contains('confirm-password')){ const form=el.closest('form'); const main=form&&form.querySelector('.main-password'); if(el.value){ bad=!main||el.value!==main.value; success=!bad&&main&&main.value.length>=6; }} const live=show || el.type==='email' || el.type==='password' || el.classList.contains('confirm-password'); const field=el.closest('.field'); if(field){field.classList.toggle('has-error',bad && live); field.classList.toggle('has-success',success && live); el.classList.toggle('invalid',bad && live); el.classList.toggle('valid',success && live);} return !bad; }
function dismissToast(el){ el.style.opacity='0'; el.style.transform='translateY(-6px)'; el.style.transition='all 0.18s ease-out'; setTimeout(()=>el.remove(),180); }
function initDjangoToasts(){ document.querySelectorAll('[data-django-toast]').forEach(el=>{ if(el.dataset.boundToastDismiss) return; el.dataset.boundToastDismiss='true'; setTimeout(()=>dismissToast(el),3200); }); }
window.taToast = function toast(message,type='good'){ const wrap=document.querySelector('.toast-wrap')||document.body.appendChild(Object.assign(document.createElement('div'),{className:'toast-wrap'})); const el=document.createElement('div'); el.className='toast '+type; const label=type==='bad'?'Error':type==='warn'?'Notice':'Done'; el.innerHTML=`<span class="dot ${type}"></span><div><b>${label}</b><span>${message}</span></div>`; wrap.appendChild(el); setTimeout(()=>{el.style.opacity='0';el.style.transform='translateY(-6px)';setTimeout(()=>el.remove(),180)},3200); }
function toast(message,type='good') { window.taToast(message, type); }
function initModals(){
  if(document.documentElement.dataset.boundModal) return;
  document.documentElement.dataset.boundModal='true';
  document.addEventListener('click',function(e){
    var openBtn=e.target.closest('[data-modal-open]');
    if(openBtn){
      e.preventDefault();
      e.stopImmediatePropagation();
      var modal=document.querySelector('[data-modal="'+openBtn.dataset.modalOpen+'"]')||document.getElementById(openBtn.dataset.modalOpen);
      if(modal){
        modal.hidden=false;
        document.body.classList.add('modal-open');
        applyLanguage(localStorage.getItem('ta-lang')||'fr');
        var close=modal.querySelector('[data-modal-close]');
        if(close) close.focus({preventScroll:true});
      }
      return;
    }
    var closeBtn=e.target.closest('[data-modal-close]');
    if(closeBtn){
      e.preventDefault();
      e.stopImmediatePropagation();
      var modal=closeBtn.closest('[data-modal]');
      if(modal) closeModal(modal);
      return;
    }
    var backdrop=e.target.closest('[data-modal]');
    if(backdrop && e.target===backdrop){
      closeModal(backdrop);
    }
  });
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      var open=document.querySelectorAll('[data-modal]:not([hidden])');
      for(var i=0;i<open.length;i++) closeModal(open[i]);
    }
  });
}
function closeModal(modal){ modal.hidden=true; if(!document.querySelector('[data-modal]:not([hidden])')) document.body.classList.remove('modal-open'); }
function initSavedJobsEmptyState(){
  const grid=document.querySelector('[data-saved-jobs-grid]');
  if(!grid || grid.querySelector('.job-card')) return;
  if(grid.dataset.emptyRendered) return;
  grid.dataset.emptyRendered='true';
  grid.innerHTML=`<div class="empty-state" style="border:1px solid var(--line);border-radius:var(--radius);background:var(--panel);box-shadow:var(--shadow2);padding:52px 22px;"><div class="empty-ill" style="margin:0 auto 16px auto;">✓</div><h2 class="h2">Aucune offre sauvegardée</h2><p class="subtitle" style="margin:0 auto 24px auto;max-width:500px;">Sauvegardez les offres intéressantes pour les comparer plus tard.</p><a href="/jobs/" class="btn primary">Explorer les offres</a></div>`;
}

function initV15Mobile(){
  const q=(s,root=document)=>root.querySelector(s);
  const qa=(s,root=document)=>[...root.querySelectorAll(s)];
  qa('[data-open-search]').forEach(btn=>btn.addEventListener('click',()=>{
    const open=!document.body.classList.contains('index-search-open');
    document.body.classList.toggle('index-search-open',open);
    document.body.classList.remove('index-stats-open','filters-open','mobile-open');
  }));
  qa('[data-open-stats]').forEach(btn=>btn.addEventListener('click',()=>{
    const open=!document.body.classList.contains('index-stats-open');
    document.body.classList.toggle('index-stats-open',open);
    document.body.classList.remove('index-search-open','filters-open','mobile-open');
  }));
  qa('[data-open-filters]').forEach(btn=>btn.addEventListener('click',()=>{
    document.body.classList.toggle('filters-open');
    document.body.classList.remove('mobile-open','index-search-open','index-stats-open');
  }));
  qa('[data-settings-toggle]').forEach(btn=>btn.addEventListener('click',()=>{
    const id=btn.dataset.settingsToggle;
    qa('[data-settings-toggle]').forEach(b=>b.classList.toggle('active',b===btn));
    qa('.settings-mobile-section').forEach(sec=>sec.classList.toggle('mobile-section-open',sec.id===id));
  }));
  const stepToggle=q('[data-profile-step-toggle]');
  if(stepToggle){ stepToggle.addEventListener('click',()=>q('.stepper')&&q('.stepper').classList.toggle('expanded')); }
}

function initResponsiveEnhancements(){
  document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>document.body.classList.remove('mobile-open')));
  document.querySelectorAll('.mobile-filter-close').forEach(btn=>btn.addEventListener('click',()=>document.body.classList.remove('filters-open')));
  if(document.querySelector('.mobile-action-bar')) document.body.classList.add('has-mobile-bar');
}
function initAILoaders(){
  document.querySelectorAll('[data-ai-loader]').forEach(card=>{
    const bar=card.querySelector('.ai-progress-bar > span');
    const percent=card.querySelector('.ai-percent');
    const steps=[...card.querySelectorAll('.ai-step')];
    let base=Number(card.dataset.base||28), max=Number(card.dataset.max||88), p=base, i=0;
    const tick=()=>{
      steps.forEach((step,idx)=>step.classList.toggle('active',idx===i));
      p=Math.min(max,p+(i%2?6:4));
      if(bar) bar.style.width=p+'%';
      if(percent) percent.textContent=Math.round(p)+'%';
      i=(i+1)%steps.length;
      if(p>=max) p=base+6;
    };
    tick();
    setInterval(tick,1400);
  });
}

function initMobileSort() {
  document.querySelectorAll("[data-mobile-sort]").forEach((sort) => {
    if (sort.dataset.boundMobileSort) return;
    sort.dataset.boundMobileSort = "true";

    const button = sort.querySelector("[data-mobile-sort-button]");
    const menu = sort.querySelector("[data-mobile-sort-menu]");
    const label = sort.querySelector("[data-mobile-sort-label]");

    if (!button || !menu || !label) return;

    button.addEventListener("click", (e) => {
      e.stopPropagation();

      if (window.closeAllMobilePanels) {
        window.closeAllMobilePanels();
      }

      const willOpen = menu.hasAttribute("hidden");
      document.querySelectorAll("[data-mobile-sort-menu]").forEach((other) => {
        other.setAttribute("hidden", "");
      });

      if (willOpen) {
        menu.removeAttribute("hidden");
        button.setAttribute("aria-expanded", "true");
      } else {
        menu.setAttribute("hidden", "");
        button.setAttribute("aria-expanded", "false");
      }
    });

    menu.querySelectorAll("[data-sort-value]").forEach((item) => {
      item.addEventListener("click", (e) => {
        e.stopPropagation();

        const value = item.dataset.sortValue;
        const text = item.textContent.trim();
        label.textContent = text;

        menu.setAttribute("hidden", "");
        button.setAttribute("aria-expanded", "false");

        const url = new URL(window.location.href);
        url.searchParams.set("sort", value);
        window.location.href = url.toString();
      });
    });
  });

  if (!document.documentElement.dataset.boundMobileSortClose) {
    document.documentElement.dataset.boundMobileSortClose = "true";
    document.addEventListener("click", () => {
      document.querySelectorAll("[data-mobile-sort-menu]").forEach((menu) => {
        menu.setAttribute("hidden", "");
      });
    });
  }
}

function initAll() {
  initUI();
  initResponsiveEnhancements();
  initAILoaders();
  initV15Mobile();
  initMobileSort();
}

document.addEventListener('DOMContentLoaded', initAll);
document.body.addEventListener('htmx:afterSwap', (e) => {
  // Check if it's an error response
  if (e.detail && e.detail.xhr && e.detail.xhr.status >= 400) {
    window.taToast('Server error', 'bad');
  }
  initAll();
});
